from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Split on the uniform center divider into equal-sized panels.
    if w % 2 == 1:
        c = w // 2
        if len({row[c] for row in grid}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
        else:
            left = right = None
    else:
        left = right = None
    if left is None:
        if h % 2 != 1:
            raise ValueError("No centered divider")
        r = h // 2
        if len(set(grid[r])) != 1:
            raise ValueError("No centered divider")
        left, right = grid[:r], grid[r + 1:]

    # The panels use one shared color. Keep that color as the output field,
    # and mark positions where it occurs in both panels.
    shared = set(x for row in left for x in row) & set(x for row in right for x in row)
    if not shared:
        raise ValueError("Panels have no shared color")
    color = next(iter(shared)) if len(shared) == 1 else max(shared, key=lambda x: min(
        sum(v == x for row in left for v in row),
        sum(v == x for row in right for v in row)))
    return [[3 if left[i][j] == color and right[i][j] == color else color
             for j in range(len(left[0]))] for i in range(len(left))]
